      nonAsciiChars.add(char);
    } else {
      cleaned += char;
    }
  }

  netlist = cleaned;

  // Parse Confidence level from trailing text
  let confidence: 'high' | 'medium' | 'low' | undefined;
  const confidenceMatch = raw.match(/Confidence:\s*(high|medium|low)/i);
  if (confidenceMatch) {
