import { describe, it, expect, beforeEach, vi } from 'vitest';
import { OpenAIAdapter } from '@/lib/llm/openai';
import { LLMError } from '@/lib/llm/adapter';

// Mock fetch globally
global.fetch = vi.fn();

describe('OpenAIAdapter', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

