        abortController.abort();
        return Promise.reject(new DOMException('Aborted', 'AbortError'));
      });

      const adapter = new OpenAIAdapter(
        'https://api.openai.com/v1',
        'test-key',
        'gpt-4o-mini',
        'gpt-4o-mini'
      );

