      const mockResponse = {
        choices: [
          {
            message: {
              content: '```spice\ntest\n.end\n```\nConfidence: low',
            },
          },
        ],
      };

      vi.mocked(global.fetch).mockResolvedValueOnce(
        new Response(JSON.stringify(mockResponse), { status: 200 })
      );

