Test Ω
.end
\`\`\`
Confidence: high
- Some ambiguity in the schematic`;

      const result = parseNetlistFromResponse(response);

      expect('error' in result).toBe(false);
      if (!('error' in result)) {
        expect(result.note).toContain('ambiguity');
        expect(result.note).toContain('Stripped non-ASCII');
      }
