        'https://api.openai.com/v1',
        'test-key',
        'gpt-4o-mini',
        'gpt-4o-mini'
      );

      try {
        await adapter.transcribeSchematic('data:image/png;base64,abc');
      } catch (err) {
        expect(err).toBeInstanceOf(LLMError);
        if (err instanceof LLMError) {
          expect(err.kind).toBe('network');
        }
      }
    });
  });
});

