      expect(logs).not.toContain('super-secret-key');

      // Verify key is only in Authorization header, never in body
      const callArgs = vi.mocked(global.fetch).mock.calls[0][1];
      if (callArgs && typeof callArgs === 'object' && 'body' in callArgs) {
        const body = callArgs.body as string;
        expect(body).not.toContain('super-secret-key');
      }

      consoleSpy.mockRestore();
    });
  });

  describe('timeout handling', () => {
    it('should timeout after 60 seconds', async () => {
      vi.useFakeTimers();

      vi.mocked(global.fetch).mockImplementation(
        () =>
          new Promise((resolve) => {
            // Never resolves to trigger timeout
            setTimeout(() => {
              resolve(
                new Response(JSON.stringify({ choices: [] }), { status: 200 })
              );
            }, 100_000);
          })
      );

      const adapter = new OpenAIAdapter(
        'https://api.openai.com/v1',
        'test-key',
        'gpt-4o-mini',
        'gpt-4o-mini'
      );

      const promise = adapter.transcribeSchematic('data:image/png;base64,abc');

      // Fast-forward to past timeout (60s)
      vi.advanceTimersByTime(61_000);

      try {
        await promise;
      } catch (err) {
        expect(err).toBeInstanceOf(LLMError);
        if (err instanceof LLMError) {
          expect(err.kind).toBe('timeout');
        }
      }

      vi.useRealTimers();
    });
  });

  describe('network error handling', () => {
    it('should handle network errors', async () => {
      vi.mocked(global.fetch).mockRejectedValueOnce(
        new TypeError('Failed to fetch')
      );

      const adapter = new OpenAIAdapter(
        'https://api.openai.com/v1',
        'test-key',
        'gpt-4o-mini',
        'gpt-4o-mini'
      );

      try {
        await adapter.transcribeSchematic('data:image/png;base64,abc');
      } catch (err) {
        expect(err).toBeInstanceOf(LLMError);
        if (err instanceof LLMError) {
          expect(err.kind).toBe('network');
        }
      }
    });
  });
});

